  "retry.maxRetries": { "label": "重试次数", "description": "API 错误的最大重试次数" },
  "retry.maxDelayMs": { "label": "最大重试延迟", "description": "重试之间的最长等待时间，单位 ms。当提供商要求的等待超过此值、且凭据或模型回退都未成功时，请求会立即失败而不是休眠（例如 Anthropic 3 小时的限流窗口）。0 表示取消上限——让会话在提供商声明的配额重置后自动恢复。" },
  "retry.waitForUsageReset": { "label": "等待用量重置", "description": "当提供商报告用量上限耗尽并给出重置时间（任何提供商的 5 小时或每周配额头）时，休眠到重置时刻，而不是超过 retry.maxDelayMs 后立即失败。等待可以中止（Esc），但也会阻塞子代理，无人值守运行请保持关闭。" },
  "retry.modelFallback": { "label": "重试模型回退", "description": "允许重试恢复时切换到已配置的回退模型" },
  "retry.usageAwareFallback": { "label": "用量感知回退", "description": "在触及硬性用量上限之前，利用可靠的编码套餐配额报告优先选择同提供商账户，其次是已配置的回退模型。普通配置的 API 密钥不参与。" },
  "retry.usageReservePct": { "label": "预留额度", "description": "剩余百分比低于此值时，将编码套餐模型视为接近上限。用量未知或未映射时保持使用主模型。" },
  "retry.usageReservePolicy": { "label": "预留策略", "description": "当同提供商的所有编码套餐账户都进入预留额度内时该怎么做。" },
  "retry.fallbackChains": { "label": "重试回退链", "description": "JSON 对象，把模型角色、模型选择器（\"provider/model-id\"）或提供商通配符（\"provider/*\"）映射到有序的回退选择器，例如 {\"default\":[\"openai/gpt-4o-mini\"],\"google-antigravity/*\":[\"google/*\",\"google-vertex/*\"]}。以模型为键的条目在该模型/提供商激活时生效，与角色无关；\"provider/*\" 条目保留失败模型的 id 并替换提供商。带 id 前缀的通配符（\"openrouter/google/*\"）为失败模型的裸 id 重新加前缀（google-antigravity/gemini-x -> openrouter/google/gemini-x），作为键时仅匹配该前缀下此提供商的 id。回退条目可携带显式思考后缀（\"provider/model:low\"、\":high\"、\":max\"、\":off\"）；裸条目继承失败轮次的强度，\"provider/*\" 条目始终继承。" },
  "retry.fallbackRevertPolicy": { "label": "回退切回策略", "description": "回退之后何时切回主模型" },
  "providers.anthropic.serverSideFallback": { "label": "Anthropic 服务端回退（Fable 5）", "description": "当 Claude Fable 5 / Mythos 5 请求被 Anthropic 的安全分类器拦截时，在服务端改用 Claude Opus 4.8 重试（Anthropic `server-side-fallback-2026-06-01` beta）。需主动开启——关闭时所有请求保持回退前的行为。" },
  "providers.autoThinkingModel": { "label": "自动思考模型", "description": "`auto` 思考等级的难度分类器：默认在线（/models 中的 TINY 角色，否则 smol），也可用本地端侧模型" },
  "providers.autoThinkingMaxEffort": { "label": "自动思考上限", "description": "`auto` 分类器可解析到的最高强度。`xhigh` 让分类器停在最高档之下一档，只有显式 `ultrathink` 才会到 `max`；`max` 则允许分类器判定为极难的一轮在暴露该档的模型上按最高档计费。" },
  "memory.backend": { "label": "记忆后端", "description": "关闭、本地摘要流水线、Mnemopi SQLite、Hindsight 远程记忆或 Sharpshooter" },
  "sharpshooter.model": { "label": "Sharpshooter 模型", "description": "抽取与合并所用的模型选择器，留空则使用 smol 角色" },
  "autolearn.enabled": { "label": "自动学习（实验性）", "description": "智能体停止后，提示它把经验教训存入记忆，并创建或增强隔离的托管技能" },
  "autolearn.autoContinue": { "label": "停止时自动运行捕获", "description": "开启后，停止时自动运行一次私有捕获轮次（消耗额外 token）；关闭时仅保留常驻的自动学习指导" },
  "mnemopi.dbPath": { "label": "Mnemopi 数据库路径", "description": "可选的 SQLite 数据库路径，默认使用智能体记忆目录" },
  "mnemopi.bank": { "label": "Mnemopi 记忆库", "description": "可选的共享记忆库基名，按项目模式据此派生项目本地记忆库" },
  "mnemopi.scoping": { "label": "Mnemopi 作用域", "description": "global = 单一共享记忆库；per-project = 每个工作目录一个独立记忆库；per-project-tagged = 项目本地写入且全局召回可见" },
  "mnemopi.embeddingVariant": { "label": "嵌入变体", "description": "本地嵌入模型族。en = 更强的英文模型；multilingual = 跨语言模型。更改后下次启动会重建既有记忆嵌入" },
  "mnemopi.autoRecall": { "label": "Mnemopi 自动召回", "description": "在每个会话的第一轮将本地记忆召回进来" },
  "mnemopi.autoRetain": { "label": "Mnemopi 自动保留", "description": "把已完成的对话轮次保留在本地 Mnemopi 记忆中" },
  "mnemopi.polyphonicRecall": { "label": "Mnemopi 多声部召回", "description": "启用四路召回（向量、图谱、事实、时间），以倒数排名融合合并" },
  "mnemopi.enhancedRecall": { "label": "Mnemopi 增强召回", "description": "为重复及相似的召回查询启用分层查询结果缓存" },
  "mnemopi.proactiveLinking": { "label": "Mnemopi 主动链接", "description": "新记忆存入时即写入情节图谱，并与相关实体和记忆建立链接" },
  "mnemopi.noEmbeddings": { "label": "Mnemopi 禁用嵌入", "description": "改用确定性的仅 FTS 召回，而非向量嵌入" },
  "mnemopi.embeddingModel": { "label": "Mnemopi 嵌入模型", "description": "高级：显式指定覆盖嵌入变体的模型 id，留空则使用 mnemopi.embeddingVariant" },
  "mnemopi.embeddingApiUrl": { "label": "Mnemopi 嵌入 API 地址", "description": "可选的 OpenAI 兼容嵌入端点，传递给 Mnemopi" },
  "mnemopi.embeddingApiKey": { "label": "Mnemopi 嵌入 API 密钥", "description": "可选的嵌入 API 密钥，传递给 Mnemopi" },
  "mnemopi.llmMode": { "label": "Mnemopi LLM 模式", "description": "不使用 LLM、在线微型模型（/models 中的 TINY 角色，否则 @smol），或远程 OpenAI 兼容端点" },
  "mnemopi.llmBaseUrl": { "label": "Mnemopi LLM 基础地址", "description": "可选的 OpenAI 兼容 LLM 端点，用于 Mnemopi 远程模式" },
