  "hindsight.bankId": { "label": "Hindsight 记忆库 ID", "description": "记忆库标识符（默认：项目名称）" },
  "hindsight.scoping": { "label": "Hindsight 作用域", "description": "global = 单一共享记忆库；per-project = 每个工作目录一个独立记忆库；per-project-tagged = 共享记忆库并带项目标签，召回时合并全局与项目记忆" },
  "hindsight.autoRecall": { "label": "Hindsight 自动召回", "description": "在每个会话的第一轮召回记忆" },
