  "hindsight.mentalModelsEnabled": { "label": "Hindsight 心智模型", "description": "启动时把精选的反思摘要（心智模型）读入开发者指令。加载记忆库上已有的模型——不会写入。配合 hindsight.mentalModelAutoSeed 可同时自动创建内置种子集" },
  "hindsight.mentalModelAutoSeed": { "label": "Hindsight 心智模型自动播种", "description": "会话开始时创建记忆库上尚不存在的内置心智模型（项目约定、项目决策、用户偏好）" },
  "edit.mode": { "label": "编辑模式", "description": "选择编辑工具变体（replace、patch、hashline 或 apply_patch）" },
