  "edit.recoverInlineEdits": { "label": "恢复内联编辑载荷", "description": "把模型以纯文本发出的编辑载荷转换为编辑工具调用并执行" },
  "edit.blockAutoGenerated": { "label": "阻止编辑自动生成文件", "description": "防止编辑疑似自动生成的文件（protoc、sqlc、swagger 等）" },
  "edit.enforceSeenLines": { "label": "强制已见行防护", "description": "拒绝锚定在先前读取或搜索中未完整展示过的行上的编辑" },
