  "edit.autoRepair.enabled": { "label": "自动修复解析回归", "description": "编辑破坏文件的 AST 解析时，让 smol 模型修复破损区域（经重新解析验证，失败则回退为警告）" },
  "readLineNumbers": { "label": "行号", "description": "默认在读取工具输出前加上行号" },
