  "read.summarize.unfoldUntil": { "label": "读取摘要展开目标", "description": "广度优先展开可省略片段，直到摘要至少达到该可见行数。0 则只保留最外层的省略" },
  "read.summarize.unfoldLimit": { "label": "读取摘要展开上限", "description": "广度优先展开时摘要规模的硬上限。某次展开若会使显示行数超过该值，则跳过它（该片段保持折叠），继续展开其余片段" },
