  "bash.direnvLoadTimeoutMs": { "label": "direnv 加载超时（毫秒）", "description": "等待首次 `direnv export` 的最长时间（冷启动的 devenv shell 可能较慢）；超时后会话在没有 direnv 环境的情况下运行" },
  "shellMinimizer.enabled": { "label": "Shell 精简器", "description": "在返回给智能体之前压缩冗长的 shell 输出（git、npm、cargo 等）" },
