  "eval.py": { "label": "Python 求值后端", "description": "允许 eval 工具把 Python 单元格分派给 IPython 内核" },
  "eval.js": { "label": "JavaScript 求值后端", "description": "允许 eval 工具把 JavaScript 单元格分派给进程内运行时" },
  "eval.tools.enabled": { "label": "求值定义的工具", "description": "允许 eval 单元格定义工具（Python 中的 @tool、JS 中的 tool(fn)），供 task、agent() 和 workpool() 子智能体调用" },
  "eval.workpool.freshAgents": { "label": "全新工作池代理", "description": "为每个工作池条目都新起一个子智能体，而非复用工作者或批量处理排队条目" },
  "eval.autoBackground.enabled": { "label": "求值自动转后台", "description": "自动把长时间运行的求值单元格转入后台，并稍后送达结果" },
  "python.kernelMode": { "label": "Python 内核模式", "description": "让 IPython 内核跨 eval 调用保持存活，或每次重新启动" },
  "python.interpreter": { "label": "Python 解释器", "description": "可选：指定确切 Python 可执行文件的路径。设置后会跳过自动 Python 运行时发现" },
  "providers.memoryModel": { "label": "记忆模型", "description": "用于事实抽取与合并的 Mnemopi LLM：默认在线（/models 中的 TINY 角色，否则 smol/远程），或本地设备端模型" },
  "plan.enabled": { "label": "计划模式", "description": "启用计划模式，在执行前进行只读探索与规划" },
