  "plan.autosaveDir": { "label": "自动保存目录", "description": "计划自动保存的目录。支持 ~、绝对路径和相对 cwd 的路径。留空则使用 <project>/.omp/plans/。" },
  "goal.enabled": { "label": "目标模式", "description": "启用按会话的目标模式以及隐藏的 goal 工具" },
  "goal.statusInFooter": { "label": "底栏显示目标状态", "description": "在状态栏的目标指示旁显示 token 预算" },
  "goal.continuationModes": { "label": "目标续跑模式", "description": "允许活动目标在轮次之间自动续跑的运行模式" },
  "title.refreshOnReplan": { "label": "重新规划时刷新标题", "description": "在 todo 初始化触发的重新规划之后刷新生成的会话标题，除非该标题由用户设置" },
  "task.eager": { "label": "优先委派任务", "description": "把工作委派给子智能体的推行力度" },
  "task.batch": { "label": "批量任务调用", "description": "把 task 工具切换为批量形态：一次调用携带 { context, tasks[] }——每个条目对应一个子智能体，可为每个条目指定 agent（默认取会话的 spawn 策略 agent）、按条目隔离，并有一段必需的共享 context 前置到每个任务分配。async.enabled=true 时，每次 spawn 作为独立后台 agent 运行，具有正常的空闲/停放生命周期；否则该调用阻塞等待合并结果。关闭可恢复扁平的单次 spawn 形态。" },
  "task.enableEffort": { "label": "按任务思考力度", "description": "在 task spawn 上暴露可选的 effort 参数，允许调用方覆盖每个子智能体的思考层级" },
  "task.maxConcurrency": { "label": "最大并发任务数", "description": "同时运行的子智能体最大数量" },
  "task.enableLsp": { "label": "子智能体使用 LSP", "description": "允许经由 task 工具 spawn 的子智能体使用 lsp 工具。默认关闭以控制子智能体成本；当感知 LSP 的委派值得额外 token 时再启用。" },
  "task.maxRecursionDepth": { "label": "最大任务递归深度", "description": "子智能体可以继续 spawn 自己子智能体的层数" },
  "task.maxRuntimeMs": { "label": "子智能体最长运行时间", "description": "每个子智能体的硬性挂钟上限（ms）。0 表示禁用。用于纵深防御，拦截逃过推理层看门狗的供应商端流卡死；触发时以「超时」为由正常中止子智能体。" },
  "task.agentIdleTtlMs": { "label": "agent 空闲 TTL", "description": "空闲子智能体在被停放到磁盘之前于内存中保持存活的时长（ms）。被停放的 agent 收到消息或被恢复时会自动复活。0 表示空闲 agent 一直存活到退出。" },
  "task.softRequestBudget": { "label": "子智能体软性请求预算", "description": "每个子智能体的软性请求预算（每次运行的 assistant 请求数）。超出后注入一条收尾引导提示（见 task.softRequestBudgetNotice）；达到预算的 1.5 倍时运行被强制停止，agent 必须交出部分发现结果。0 表示禁用该保护。内置的 scout/sonic agent 上限更低，因此低于该上限的取值对它们依然生效。" },
